def ring_waits(load):
    n = len(load)
    waits = [-1] * n
    stack = []  # slots still waiting, readings not rising
    for i in range(2 * n):
        x = load[i % n]
        while stack and load[stack[-1]] < x:
            j = stack.pop()
            waits[j] = i - j
        if i < n:
            stack.append(i)
    return waits

